/**
 * Bakes login-logo.png into JS as a data URL — WKWebView never needs to fetch a separate PNG.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const logoPath = resolve('public/login-logo.png');
const outPath = resolve('src/lib/login-logo-data.js');

if (!existsSync(logoPath)) {
  console.warn('embed-login-logo: public/login-logo.png missing — run sync-app-icon.mjs first');
  writeFileSync(
    outPath,
    "/** Generated by scripts/embed-login-logo.mjs */\nexport const LOGIN_LOGO_DATA_URL = '';\n",
  );
  process.exit(0);
}

const bytes = readFileSync(logoPath);
const dataUrl = `data:image/png;base64,${bytes.toString('base64')}`;
writeFileSync(
  outPath,
  `/** Generated by scripts/embed-login-logo.mjs — do not edit */\nexport const LOGIN_LOGO_DATA_URL = '${dataUrl}';\n`,
);
console.log(`Embedded login logo (${bytes.length} bytes) -> ${outPath}`);
